WITH session_summary AS (SELECT session_id, COUNT(*) AS web_event_count, SUM(duration_sec) AS total_duration_sec FROM web_events WHERE TO_DATE(event_time) >= '2024-08-13' GROUP BY session_id) SELECT s.id, s.started_at, ss.web_event_count, ss.total_duration_sec FROM sessions s LEFT JOIN session_summary ss ON s.id = ss.session_id WHERE ss.web_event_count > 9 ORDER BY id DESC, web_event_count
